// Behaviour for docs/site/logical-map.html — the repo map as a lifecycle flow.
//
// Hand-written; the page itself is generated by .github/scripts/build-logical-map.js,
// which also computes the layout. Nothing here moves a box: the generator proves
// on the computed geometry that no arrow crosses a box it does not connect, and
// letting a reader drag boxes would void that proof (the previous map let them,
// and two of its worst defects lived only in layouts a reader had made).
//
// What this file does: pan and zoom, search, and TRACE — click a box to light up
// every connection that leads to it and every connection it leads to, start to
// finish, with the line in the files that proves each one.
(() => {
  'use strict';
  const data = JSON.parse(document.getElementById('mapdata').textContent);
  const wrap = document.getElementById('wrap');
  const vp = document.getElementById('viewport');
  const panel = document.getElementById('panel');
  const search = document.getElementById('search');
  const boxes = new Map([...document.querySelectorAll('.n')].map(n => [n.dataset.id, n]));
  const lines = [...document.querySelectorAll('.e')];
  const clamp = (v, lo, hi) => Math.min(hi, Math.max(lo, v));

  /* -------------------------------------------------------------- graph */
  const out = new Map(), inn = new Map();
  data.edges.forEach((e, i) => {
    out.set(e.a, [...(out.get(e.a) ?? []), i]);
    inn.set(e.b, [...(inn.get(e.b) ?? []), i]);
  });
  // A re-sync loops back to an earlier stage. Following it would make every
  // file upstream of every other, so a trace stops at it and lists it instead.
  const follows = i => data.edges[i].kind !== 'ret' && !hiddenEdge(i);
  function walk(start, dir) {
    const seen = new Set([start]), used = new Set(), q = [start];
    while (q.length) {
      const n = q.shift();
      for (const i of (dir === 'down' ? out : inn).get(n) ?? []) {
        if (!follows(i)) continue;
        const m = dir === 'down' ? data.edges[i].b : data.edges[i].a;
        if (hiddenNode(m)) continue;
        used.add(i);
        if (!seen.has(m)) { seen.add(m); q.push(m); }
      }
    }
    seen.delete(start);
    return { nodes: seen, edges: used };
  }

  /* ---------------------------------------------------------- pan & zoom */
  let scale = 1, px = 0, py = 0;
  const paint = () => { vp.style.transform = `translate(${px}px,${py}px) scale(${scale})`; };
  function fit() {
    const r = wrap.getBoundingClientRect();
    const { w, h } = data.size;
    scale = clamp(Math.min((r.width - 32) / w, (r.height - 32) / h), 0.15, 1.4);
    px = (r.width - w * scale) / 2;
    py = Math.max(16, (r.height - h * scale) / 2);
    paint();
  }
  const zoomAt = (k, mx, my) => {
    const next = clamp(scale * k, 0.15, 3);
    px = mx - (mx - px) * (next / scale);
    py = my - (my - py) * (next / scale);
    scale = next; paint();
  };
  const zoomBy = k => { const r = wrap.getBoundingClientRect(); zoomAt(k, r.width / 2, r.height / 2); };
  // Bring a box into view, at a readable scale, without losing the context.
  function reveal(id) {
    const b = boxes.get(id);
    if (!b) return;
    const r = wrap.getBoundingClientRect();
    if (scale < 0.8) scale = 0.9;
    const x = parseFloat(b.style.left) + parseFloat(b.style.width) / 2;
    const y = parseFloat(b.style.top) + parseFloat(b.style.height) / 2;
    const room = panel.hidden || innerWidth <= 800 ? r.width : r.width - 390;
    px = room / 2 - x * scale;
    py = r.height / 2 - y * scale;
    paint();
  }

  // Scroll PANS; pinch or ctrl/cmd+scroll zooms. Treating every wheel event as
  // zoom broke trackpads: a sideways swipe has deltaY 0 and silently zoomed out.
  wrap.addEventListener('wheel', ev => {
    if (ev.target.closest('#panel, .legend')) return;   // let those scroll
    ev.preventDefault();
    if (ev.ctrlKey || ev.metaKey) {
      const r = wrap.getBoundingClientRect();
      zoomAt(ev.deltaY < 0 ? 1.12 : 1 / 1.12, ev.clientX - r.left, ev.clientY - r.top);
      return;
    }
    const sideways = ev.shiftKey && ev.deltaX === 0;   // mice have no deltaX
    px -= sideways ? ev.deltaY : ev.deltaX;
    py -= sideways ? 0 : ev.deltaY;
    paint();
  }, { passive: false });

  let suppressClick = false;
  // Drag the canvas (or middle-drag anywhere) to pan. A press that moves less
  // than a few pixels is still a click on whatever is underneath.
  let pan = null;
  wrap.addEventListener('pointerdown', ev => {
    suppressClick = false;   // a stale flag from a drag with no click must not eat this one
    if (ev.pointerType === 'touch' && touches.size >= 1) return;
    if (ev.target.closest('#panel, .legend')) return;
    if (ev.button !== 0 && ev.button !== 1) return;
    pan = { x: ev.clientX, y: ev.clientY, px, py, moved: false, id: ev.pointerId, middle: ev.button === 1 };
    if (ev.button === 1) ev.preventDefault();
  });
  wrap.addEventListener('pointermove', ev => {
    if (!pan || ev.pointerId !== pan.id || pinch) return;
    const dx = ev.clientX - pan.x, dy = ev.clientY - pan.y;
    if (!pan.moved && Math.hypot(dx, dy) < 5) return;
    if (!pan.moved) { pan.moved = true; wrap.classList.add('grabbing'); wrap.setPointerCapture(ev.pointerId); }
    px = pan.px + dx; py = pan.py + dy; paint();
  });
  const endPan = () => {
    // Only a primary-button drag is followed by a click to swallow; a middle
    // drag ends in auxclick, and a flag left armed would eat the next real click.
    if (pan?.moved && !pan.middle) suppressClick = true;
    pan = null; wrap.classList.remove('grabbing');
  };
  wrap.addEventListener('pointerup', endPan);
  wrap.addEventListener('pointercancel', endPan);
  // A drag that started on a box must not also select it.
  wrap.addEventListener('click', ev => {
    // ev.detail 0 is a keyboard activation (Enter/Space on a box): never a drag.
    if (suppressClick && ev.detail !== 0) { suppressClick = false; ev.stopPropagation(); ev.preventDefault(); }
  }, true);

  // Two-finger pinch on a touch screen. Capture phase, so a finger landing on a
  // box still counts.
  const touches = new Map();
  let pinch = null;
  const spread = () => {
    const [a, b] = [...touches.values()];
    return { d: Math.hypot(a.x - b.x, a.y - b.y), mx: (a.x + b.x) / 2, my: (a.y + b.y) / 2 };
  };
  wrap.addEventListener('pointerdown', ev => {
    if (ev.pointerType !== 'touch') return;
    touches.set(ev.pointerId, { x: ev.clientX, y: ev.clientY });
    if (touches.size === 2) { pan = null; pinch = { d: spread().d, scale, px, py }; }
  }, true);
  wrap.addEventListener('pointermove', ev => {
    if (ev.pointerType !== 'touch' || !touches.has(ev.pointerId)) return;
    touches.set(ev.pointerId, { x: ev.clientX, y: ev.clientY });
    if (touches.size !== 2 || !pinch) return;
    ev.preventDefault();
    const now = spread(), r = wrap.getBoundingClientRect();
    const next = clamp(pinch.scale * (now.d / (pinch.d || 1)), 0.15, 3);
    const mx = now.mx - r.left, my = now.my - r.top;
    px = mx - (mx - pinch.px) * (next / pinch.scale);
    py = my - (my - pinch.py) * (next / pinch.scale);
    scale = next; paint();
  }, true);
  for (const t of ['pointerup', 'pointercancel']) {
    wrap.addEventListener(t, ev => {
      touches.delete(ev.pointerId);
      if (touches.size < 2) pinch = null;
    }, true);
  }

  /* ---------------------------------------------------------- filtering */
  const hidden = { self: false, vendor: false, kinds: new Set() };
  const hiddenNode = id => (hidden.self && id.startsWith('self:')) || (hidden.vendor && id.startsWith('vendor:'));
  const hiddenEdge = i => {
    const e = data.edges[i];
    return hidden.kinds.has(e.kind) || hiddenNode(e.a) || hiddenNode(e.b);
  };
  function applyHidden() {
    for (const [id, b] of boxes) b.classList.toggle('gone', hiddenNode(id));
    lines.forEach((g, i) => g.classList.toggle('gone', hiddenEdge(i)));
    if (selected && hiddenNode(selected)) clear(); else if (selected) trace(selected, false);
  }

  /* -------------------------------------------------------------- trace */
  let selected = null;
  const label = id => data.nodes[id].label;
  const esc = s => String(s).replace(/[&<>"]/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));
  function trace(id, move = true) {
    selected = id;
    const up = walk(id, 'up'), down = walk(id, 'down');
    const onN = new Set([id, ...up.nodes, ...down.nodes]);
    const onE = new Set([...up.edges, ...down.edges]);
    wrap.classList.add('tracing');
    for (const [n, b] of boxes) { b.classList.toggle('on', onN.has(n)); b.classList.toggle('sel', n === id); }
    lines.forEach((g, i) => g.classList.toggle('on', onE.has(i)));
    showPanel(id, up, down);
    if (move) reveal(id);
  }
  function clear() {
    selected = null;
    wrap.classList.remove('tracing');
    for (const b of boxes.values()) b.classList.remove('on', 'sel');
    lines.forEach(g => g.classList.remove('on'));
    panel.hidden = true;
    panel.innerHTML = '';
  }
  function item(i, other) {
    const e = data.edges[i], k = data.kinds[e.kind];
    const where = e.ev.line ? `${e.ev.file}:${e.ev.line}` : e.ev.file;
    return `<li style="--k:${k.color}"><span class="verb">${esc(e.words)}</span> `
      + `<button type="button" data-go="${esc(other)}">${esc(label(other))}</button>`
      + `<span class="ev">${esc(where)} — ${esc(e.ev.text)}</span></li>`;
  }
  function showPanel(id, up, down) {
    const n = data.nodes[id];
    const stage = data.stages.findIndex(s => s.id === n.stage);
    const ins = (inn.get(id) ?? []).filter(i => !hiddenEdge(i));
    const outs = (out.get(id) ?? []).filter(i => !hiddenEdge(i));
    const meta = [
      `Stage ${stage + 1} · ${data.stages[stage].label}`,
      n.path, data.delivery[n.del],
      n.cls ? `class: ${n.cls}` : null, n.cmp ? `compartment: ${n.cmp}` : null,
      n.files ? `${n.files} files` : null, n.blurb,
    ].filter(Boolean).map(esc).join('<br>');
    panel.innerHTML = `<button type="button" class="x" aria-label="Close">×</button>`
      + `<h3>${esc(n.label)}</h3><p class="meta">${meta}</p>`
      + `<p class="meta"><b>${up.nodes.size}</b> upstream · <b>${down.nodes.size}</b> downstream</p>`
      + (ins.length ? `<h4>Comes from (${ins.length})</h4><ul>${ins.map(i => item(i, data.edges[i].a)).join('')}</ul>` : '')
      + (outs.length ? `<h4>Leads to (${outs.length})</h4><ul>${outs.map(i => item(i, data.edges[i].b)).join('')}</ul>` : '');
    panel.hidden = false;
  }
  panel.addEventListener('click', ev => {
    // Stop here: trace() rebuilds the panel, so by the time this click bubbled
    // to the canvas its target would be detached and read as a click on empty
    // space — which clears the trace it just started.
    ev.stopPropagation();
    const go = ev.target.closest('[data-go]');
    if (go) { trace(go.dataset.go); boxes.get(go.dataset.go)?.focus({ preventScroll: true }); return; }
    if (ev.target.closest('.x')) clear();
  });
  for (const [id, b] of boxes) {
    b.addEventListener('click', () => (selected === id ? clear() : trace(id, false)));
    // Hover shows a box's own connections without committing to a trace.
    b.addEventListener('pointerenter', () => {
      if (selected) return;
      for (const i of [...(out.get(id) ?? []), ...(inn.get(id) ?? [])]) lines[i].classList.add('hov');
    });
    b.addEventListener('pointerleave', () => lines.forEach(g => g.classList.remove('hov')));
  }
  // Clicking empty canvas clears.
  wrap.addEventListener('click', ev => {
    if (!ev.target.closest('.n, #panel, .legend, .e')) clear();
  });
  lines.forEach((g, i) => g.addEventListener('click', () => trace(data.edges[i].b)));

  /* ------------------------------------------------------------- search */
  function runSearch() {
    const q = search.value.trim().toLowerCase();
    let first = null;
    for (const [id, b] of boxes) {
      const hit = !!q && b.dataset.search.includes(q) && !hiddenNode(id);
      b.classList.toggle('hit', hit);
      b.classList.toggle('miss', !!q && !hit);
      if (hit && !first) first = id;
    }
    return first;
  }
  search.addEventListener('input', runSearch);
  search.addEventListener('keydown', ev => {
    if (ev.key === 'Enter') { const id = runSearch(); if (id) trace(id); }
  });

  /* ------------------------------------------------------------ toggles */
  const toggle = (btnId, fn) => {
    const btn = document.getElementById(btnId);
    btn.addEventListener('click', () => {
      const on = btn.getAttribute('aria-pressed') !== 'true';
      btn.setAttribute('aria-pressed', String(on));
      fn(on);
    });
  };
  toggle('t_self', on => { hidden.self = on; applyHidden(); });
  toggle('t_vendor', on => { hidden.vendor = on; applyHidden(); });
  for (const kt of document.querySelectorAll('.kt')) {
    kt.addEventListener('click', () => {
      const on = kt.getAttribute('aria-pressed') === 'true';
      kt.setAttribute('aria-pressed', String(!on));
      if (on) hidden.kinds.add(kt.dataset.kind); else hidden.kinds.delete(kt.dataset.kind);
      applyHidden();
    });
  }
  document.getElementById('t_fit').addEventListener('click', fit);
  document.getElementById('zin').addEventListener('click', () => zoomBy(1.2));
  document.getElementById('zout').addEventListener('click', () => zoomBy(1 / 1.2));

  /* ----------------------------------------------------------- keyboard */
  addEventListener('keydown', ev => {
    if (ev.key === 'Escape') {
      if (search.value) { search.value = ''; runSearch(); }
      clear();
      return;
    }
    if (ev.target.matches('input, textarea')) return;
    const step = ev.shiftKey ? 240 : 70;
    switch (ev.key) {
      case 'ArrowLeft':  px += step; break;
      case 'ArrowRight': px -= step; break;
      case 'ArrowUp':    py += step; break;
      case 'ArrowDown':  py -= step; break;
      case '+': case '=': zoomBy(1.2); return;
      case '-': case '_': zoomBy(1 / 1.2); return;
      default: return;
    }
    ev.preventDefault();
    paint();
  });
  // Tabbing to a box that is off screen brings it into view.
  for (const b of boxes.values()) {
    b.addEventListener('focus', () => {
      const r = b.getBoundingClientRect(), w = wrap.getBoundingClientRect();
      if (r.right < w.left || r.left > w.right || r.bottom < w.top || r.top > w.bottom) reveal(b.dataset.id);
    });
  }

  fit();
  addEventListener('resize', () => { if (!selected) fit(); });
  // For the UI suite: the computed graph walk, so a test can compare the page
  // against an independent walk of the same data.
  window.__map = { trace, clear, walk, data, state: () => ({ scale, px, py, selected }) };
})();
